(-1 + kp).*omega).*1)./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2) - (epsilon.*q.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*T3.*T32.*T4)./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)) + (epsilon.*qp.*r.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*T3.*T32.*T4)./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)) - (epsilon.^3.*q.*r.*t2p.*T3.*T32.*T4)./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)) + (2.*epsilon.*q.*r.*T18.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*T3.*T32.*T7)./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)) - (2.*epsilon.*q.*r.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*T32.*T4.*T8)./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)) + (2.*q.*r.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*T2.*(-(epsilon.*(-1 + kp).*cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3))) + epsilon.*-((-1 + kp).*1.*sin((-1 + kp).*omega)).*(-(epsilon.^2.*P.*sin(omega)) - r.*sin(omega) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))))./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)) + (epsilon.^2.*q.*r.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*T3.*T32.*T4.*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)))./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2 - (q.*r.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*T3.*T4.*(epsilon.*T45 + epsilon.*cos((-1 + kp).*omega).*1.*(cos(omega) + epsilon.^2.*Pp.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3)) + epsilon.*1.*sin((-1 + kp).*omega).*(-((1 + epsilon.^2.*Pp).*sin(omega)) + epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3))))./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3))))./(q.^3.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)))));
        j33kpF = (-((epsilon.*r.^2.*T16.*T18.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).^2.*T3.*(cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)) - 1.*sin((-1 + kp).*omega).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))))./(q.^2.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)))));
        j13kpF_FFT = real(fft(j13kpF, [], 2)) / Ntheta;
        jacTotal(1,3 + Nb + (kp - 1),rowsF,:) = reshape(j13kpF_FFT(:, mF+1).', [1,1,nmF, Nq]);
        j23kpF_FFT = real(fft(j23kpF, [], 2)) / Ntheta;
        jacTotal(2,3 + Nb + (kp - 1),rowsF,:) = reshape(j23kpF_FFT(:, mF+1).', [1,1,nmF, Nq]);    
        j33kpF_FFT = real(fft(j33kpF, [], 2)) / Ntheta;
        jacTotal(3,3 + Nb + (kp - 1),rowsF,:) = reshape(j33kpF_FFT(:, mF+1).', [1,1,nmF, Nq]);    
    end
	% --- resP ---
	gamma = 3;
    jacTotal(1,2, gamma, :) = mean((-(T16./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2)), 2) ;
    jacTotal(1,3, gamma, :) = mean(((epsilon.*T16.*cos(omega) + (1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).*(-1 - epsilon.^2.*Pp + deltap.*epsilon.*cos(omega) - epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3)))./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2), 2) ;
    jacTotal(2,2, gamma, :) = mean(((epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3))./(epsilon - delta.*epsilon.^3 + epsilon.^4.*P.*cos(omega) + epsilon.^2.*r.*cos(omega) + epsilon.^3.*sum(cos((-1 + ms).*omega).*S,3))), 2) ;
    jacTotal(2,3, gamma, :) = mean(((-(epsilon.^2.*P) - r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3))), 2) ;
	for kp = 2:(Ns+1)
			jacTotal(1, 3 + Nb + (kp - 1), gamma, :) = mean((-((epsilon.^3.*P.*T45.*cos(omega) - epsilon.*T16.*cos((-1 + kp).*omega).*1 + T45.*(1 - delta.*epsilon.^2 + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)))./(epsilon.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2))), 2) ;
			jacTotal(2, 3 + Nb + (kp - 1), gamma, :) = mean(((-(cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3))) + 1.*sin((-1 + kp).*omega).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./(epsilon.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)))), 2) ;
    end

	% --- resB modes ---
    j11B = ((-2.*epsilon.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).*(q.^2.*(1 + epsilon.*sum(Bs.*cos(mb.*omega),3)).^2 + epsilon.^2.*r.^2.*T3.*T4.*(1 - dbetapardB.*epsilon.^2 + epsilon.*sum(Bs.*cos(mb.*omega),3)).^2))./(q.^2.*(1 - dbetapardB.*epsilon.^2 + epsilon.*sum(Bs.*cos(mb.*omega),3)).^2.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2));
    j12B = ((-2.*epsilon.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).^2.*(q.^2.*(1 + epsilon.*sum(Bs.*cos(mb.*omega),3)).^2 + epsilon.^2.*r.^2.*T3.*T4.*(1 - dbetapardB.*epsilon.^2 + epsilon.*sum(Bs.*cos(mb.*omega),3)).^2))./(q.^2.*(1 - dbetapardB.*epsilon.^2 + epsilon.*sum(Bs.*cos(mb.*omega),3)).^2.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^3));
    j22B =  ((-2.*epsilon.^2.*r.^2.*T18.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).^2.*T3.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)))./(q.^2.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2));
    j13B = ((2.*(epsilon - dbetapardB.*epsilon.^3 + epsilon.^3.*t2).^2.*((epsilon.^2.*r.^2.*T3.*T4.*cos(omega))./q.^2 + cos(omega)./(-1 + (dbetapardB.*epsilon.^2)./(1 + epsilon.*sum(Bs.*cos(mb.*omega),3))).^2 - (epsilon.*r.^2.*T4.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).*(epsilon.^2.*P + r - epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./q.^2 + (epsilon.*r.^2.*T18.*T3.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3)))./q.^2))./(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^3);
    j23B = ((2.*epsilon.^3.*r.^2.*T18.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).^2.*T3.*(epsilon.^2.*P + r - epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./(q.^2.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2));
    j11B_FFT = real(fft(j11B, [], 2)) / Ntheta;
    jacTotal(1,1,rowsB,:) = reshape(j11B_FFT(:, mB+1).', [1,1,nmB, Nq]);

    j12B_FFT = real(fft(j12B, [], 2)) / Ntheta;
    jacTotal(1,2,rowsB,:) = reshape(j12B_FFT(:, mB+1).', [1,1,nmB, Nq]);

    j22B_FFT = real(fft(j22B, [], 2)) / Ntheta;
    jacTotal(2,2,rowsB,:) = reshape(j22B_FFT(:, mB+1).', [1,1,nmB, Nq]);

    j13B_FFT = real(fft(j13B, [], 2)) / Ntheta;
    jacTotal(1,3,rowsB,:) = reshape(j13B_FFT(:, mB+1).', [1,1,nmB, Nq]);

    j23B_FFT = real(fft(j23B, [], 2)) / Ntheta;
    jacTotal(2,3,rowsB,:) = reshape(j23B_FFT(:, mB+1).', [1,1,nmB, Nq]);
    for lp = 1:Nb
        j13lbB =  (2.*cos(lp.*omega).*(1 + epsilon.*sum(Bs.*cos(mb.*omega),3)).*(1 + ((epsilon - dbetapardB.*epsilon.^3 + epsilon.^3.*t2).^2.*(-dbetapardB + d2betapardB2.*(1 + epsilon.*sum(Bs.*cos(mb.*omega),3))))./((-1 + dbetapardB.*epsilon.^2 - epsilon.*sum(Bs.*cos(mb.*omega),3)).^3.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2)));
        j13lbB_FFT = real(fft(j13lbB, [], 2)) / Ntheta;
        jacTotal(1, 3 + lp, rowsB, :) = reshape(j13lbB_FFT(:, mB+1).', [1,1,nmB, Nq]);
    end
    for kp = 2:(Ns+1)
        T32 = cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)) - 1.*sin((-1 + kp).*omega).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3));
        T33 = -((-1 + kp).*cos((-1 + kp).*omega).*1.*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3))) - -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3));
        T41 = -2.*((-1 + kp).*cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)) + -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)));

        j13kpB = (((epsilon - dbetapardB.*epsilon.^3 + epsilon.^3.*t2).^2.*((2.*epsilon.^2.*r.^2.*T3.*T4.*cos((-1 + kp).*omega).*1)./q.^2 + (2.*cos((-1 + kp).*omega).*1)./(-1 + (dbetapardB.*epsilon.^2)./(1 + epsilon.*sum(Bs.*cos(mb.*omega),3))).^2 + (2.*epsilon.*r.^2.*T18.*T3.*T33.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)))./q.^2 - (epsilon.*r.^2.*T4.*T41.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)))./q.^2))./(epsilon.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^3));
        j23kpB = ((2.*epsilon.^2.*r.^2.*T18.*(1 - dbetapardB.*epsilon.^2 + epsilon.^2.*t2).^2.*T3.*T32)./(q.^2.*(1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).^2));

        j13kpB_FFT = real(fft(j13kpB, [], 2)) / Ntheta;
        jacTotal(1, 3 + Nb + (kp - 1), rowsB, :) = reshape(j13kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);

        j23kpB_FFT = real(fft(j23kpB, [], 2)) / Ntheta;
        jacTotal(2, 3 + Nb + (kp - 1), rowsB, :) = reshape(j23kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
    end


	%% Construct J
    totalDofs = dof_count * (3 + Nb) + (dof_count-1) *Ns;
    nCols = (3+ Nb + Ns)^2 * Nq;
    % precomputed: M_extended (totalDofs x nCols), P_templates{d} with fields i,j,v_template
    J = spalloc(totalDofs, totalDofs, 1 * nnz(M_extended));  % or a tighter nnz estimate

    for d = 1:3
        % Extract jacobian block and flatten in the SAME order P_templates was built.
        jac_d = squeeze(jacTotal(d,:,:,:));    % size: [nProfiles, nProfiles, Nq] (alpha,gamma,q)
        % permute to [q, gamma, alpha] then linearize -> ordering matches P_templates{d}.i
        jacTotal_flat = reshape(permute(jac_d, [3, 1, 2]), [], 1);   % length == nCols

        % Row-scale P template by jac values (this gives diag(jac)*P_extended)
        vP_scaled = P_templates{d}.v_template .* jacTotal_flat(P_templates{d}.i);

        % Create sparse scaled-P and accumulate J via M_extended * P_scaled
        P_scaled = sparse(P_templates{d}.i, P_templates{d}.j, vP_scaled, nCols, totalDofs);
        J = J + M_extended * P_scaled;
    end
end
